CREATE TABLE inventory(product_id UUID PRIMARY KEY,available INT NOT NULL CHECK(available>=0),reserved INT NOT NULL DEFAULT 0 CHECK(reserved>=0),version BIGINT NOT NULL DEFAULT 0);CREATE TABLE reservations(order_id UUID NOT NULL,product_id UUID NOT NULL,quantity INT NOT NULL,status VARCHAR(20) NOT NULL,PRIMARY KEY(order_id,product_id));CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
